  `source_json_file` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `rectification_deadline` date DEFAULT NULL,
  `status` enum('ongoing','completed','pending_rectification') COLLATE utf8mb4_unicode_ci DEFAULT 'ongoing',
